[{"slug":"ls-15k-showdown","groupName":"Группа А","sortOrder":1,"teamCapacity":4,"advanceToPlayoff":4,"advanceToUpper":2,"advanceToLower":2},{"slug":"ls-15k-showdown","groupName":"Группа Б","sortOrder":2,"teamCapacity":4,"advanceToPlayoff":4,"advanceToUpper":2,"advanceToLower":2},{"slug":"ls-call-to-arms-2026","groupName":"Общая группа","sortOrder":1,"teamCapacity":6,"advanceToPlayoff":4,"advanceToUpper":0,"advanceToLower":0},{"slug":"ls-draft-1","groupName":"Общая группа","sortOrder":1,"teamCapacity":4,"advanceToPlayoff":3,"advanceToUpper":0,"advanceToLower":0},{"slug":"ls-item-draft","groupName":"Общая группа","sortOrder":1,"teamCapacity":4,"advanceToPlayoff":3,"advanceToUpper":0,"advanceToLower":0},{"slug":"ls-pre-season-bash","groupName":"Общая группа","sortOrder":1,"teamCapacity":6,"advanceToPlayoff":4,"advanceToUpper":0,"advanceToLower":0},{"slug":"sd-fastcup-1","groupName":"Группа А","sortOrder":1,"teamCapacity":3,"advanceToPlayoff":2,"advanceToUpper":0,"advanceToLower":0},{"slug":"sd-fastcup-1","groupName":"Группа B","sortOrder":2,"teamCapacity":3,"advanceToPlayoff":2,"advanceToUpper":0,"advanceToLower":0}]
