$matches$::jsonb) AS source(
  slug TEXT, "matchKey" TEXT, "scheduledAt" TIMESTAMPTZ, stage TEXT,
  "groupName" TEXT, "teamA" TEXT, "teamB" TEXT,
  "scoreA" SMALLINT, "scoreB" SMALLINT, "bestOf" SMALLINT,
  "resultType" TEXT, "labelA" TEXT, "labelB" TEXT, "decisionNote" TEXT,
  "bracketRound" SMALLINT, "bracketSide" TEXT, "bracketSlot" SMALLINT,
  "winnerToKey" TEXT, "winnerToSlot" CHAR(1),
  "loserToKey" TEXT, "loserToSlot" CHAR(1),
  "eliminatedTeam" TEXT, "sortOrder" SMALLINT, "isFinal" BOOLEAN
);

INSERT INTO tournament_matches (
  tournament_id, group_id, scheduled_at, stage,
  team_a_application_id, team_b_application_id,
  team_a_score, team_b_score, best_of, status, sort_order,
  result_type, team_a_result_label, team_b_result_label, decision_note,
  bracket_round, bracket_side, bracket_slot,
  eliminated_team_application_id
)
SELECT
  tournament.id, tournament_group.id, source."scheduledAt", source.stage,
  team_a.id, team_b.id, source."scoreA", source."scoreB", source."bestOf",
  'finished', source."sortOrder", source."resultType", source."labelA",
  source."labelB", source."decisionNote", source."bracketRound",
  source."bracketSide", source."bracketSlot", eliminated_team.id
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications team_a
  ON team_a.tournament_id = tournament.id AND team_a.team_name = source."teamA"
JOIN tournament_team_applications team_b
  ON team_b.tournament_id = tournament.id AND team_b.team_name = source."teamB"
LEFT JOIN tournament_groups tournament_group
  ON tournament_group.tournament_id = tournament.id
 AND tournament_group.name = source."groupName"
LEFT JOIN tournament_team_applications eliminated_team
  ON eliminated_team.tournament_id = tournament.id
 AND eliminated_team.team_name = source."eliminatedTeam"
WHERE NOT EXISTS (
  SELECT 1 FROM tournament_matches existing
  WHERE existing.tournament_id = tournament.id
    AND existing.sort_order = source."sortOrder"
);

UPDATE tournament_matches source_match
SET winner_to_match_id = winner_match.id,
    winner_to_slot = source."winnerToSlot",
    loser_to_match_id = loser_match.id,
    loser_to_slot = source."loserToSlot"
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
LEFT JOIN imported_fastcup_matches winner_source
  ON winner_source.slug = source.slug AND winner_source."matchKey" = source."winnerToKey"
LEFT JOIN tournament_matches winner_match
  ON winner_match.tournament_id = tournament.id
 AND winner_match.sort_order = winner_source."sortOrder"
LEFT JOIN imported_fastcup_matches loser_source
  ON loser_source.slug = source.slug AND loser_source."matchKey" = source."loserToKey"
LEFT JOIN tournament_matches loser_match
  ON loser_match.tournament_id = tournament.id
 AND loser_match.sort_order = loser_source."sortOrder"
WHERE source_match.tournament_id = tournament.id
  AND source_match.sort_order = source."sortOrder";

CREATE TEMP TABLE imported_fastcup_rules ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($rules$
[{"slug":"ls-15k-showdown","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @frokeng в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-15k-showdown","sortOrder":2,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее в лигах летнего DPC-межсезонья Linken's Sphere (участие в фасткапах и Overthrow не снимает статус \"легионера\"). Исключение - один слот в команде может занять \"легионер\" (см п.12), также, можно взять второго \"легионера\" со снижением суммарного тира команды на 1."},{"slug":"ls-15k-showdown","sortOrder":3,"ruleText":"При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 36. Игроков 10 тира может быть не более одного на команду."},{"slug":"ls-15k-showdown","sortOrder":4,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одну серию (bo1/bo3) за турнир, в таком случае замену выбирает команда, но её все ещё нужно согласовать с организатором. Также, возможно заменить игрока или двух игроков в любой момент в случае форс-мажора, ограничений на такие замены нет, но замену предоставляет организатор, если замена одна - она будет на 1 тир ниже, если замен сразу две - первая на 1 тир ниже, вторая на 2 тира ниже. При использовании замены в финале более чем на одну карту, призовые команды сокращаются на 20%."},{"slug":"ls-15k-showdown","sortOrder":5,"ruleText":"На турнире предусмотрено 8 слотов для команд, формат может быть изменен."},{"slug":"ls-15k-showdown","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм с турнирым билетом, доступен для зрителей с задержкой 5 минут."},{"slug":"ls-15k-showdown","sortOrder":7,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-15k-showdown","sortOrder":8,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - 3-й уровень штрафа бонус-времени на всю серию. Опоздание более чем на 20 минут - техническое поражение на первой карте серии, вторая карта ставится на 1 час 15 минут позже старта 1-й карты, возможен досрочный старт по договоренности."},{"slug":"ls-15k-showdown","sortOrder":9,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-15k-showdown","sortOrder":10,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере. Исключение - Sakana не является легионером."},{"slug":"ls-15k-showdown","sortOrder":11,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-15k-showdown","sortOrder":12,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-15k-showdown","sortOrder":13,"ruleText":"Легионерами считаются игроки не участвовавшие в турах лиг в ходе DPC-межсезонья и сыгравшие менее 60 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-15k-showdown","sortOrder":14,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-15k-showdown","sortOrder":15,"ruleText":"Исходная таблица турнира: https://docs.google.com/spreadsheets/d/1CN2Y7eVMSgyv4Jysy1HHFLhVDjkA2rmWPRwGgFBrXTE/edit"},{"slug":"ls-15k-showdown","sortOrder":16,"ruleText":"MVP от спонсора - 1-й уровень поддержки сервера на осенний сезон (продвинутая кастомизация)"},{"slug":"ls-call-to-arms-2026","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @cy119 @son1c_ в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-call-to-arms-2026","sortOrder":2,"ruleText":"К участию в турнире допускаются игроки, прошедшие регистрацию через турнирного бота и подтверждённые администратором. У игрока должна быть открыта история матчей на игровом аккаунте. После успешной проверки администратором игрок добавляется в официальную таблицу участников турнира."},{"slug":"ls-call-to-arms-2026","sortOrder":3,"ruleText":"Начальный лимит тиров на команду составляет 34 тира. В стартовом составе команды обязательно должен присутствовать минимум один “легионер” с тиром 4-6. При добавлении каждого легионера в состав команды общий лимит тиров увеличивается на 1. ПОЯСНЕНИЕ: Обязательный легионер НЕ дает +1 к общему лимиту тиров. Максимально допустимый лимит тиров на команду — 38 тиров."},{"slug":"ls-call-to-arms-2026","sortOrder":4,"ruleText":"Команде разрешена не более одной замены за турнир. Замену можно использовать только на одной карте и она должна быть согласована с организатором. Форс-мажорные ситуации рассматриваются администрацией в индивидуальном порядке."},{"slug":"ls-call-to-arms-2026","sortOrder":5,"ruleText":"На турнире предусмотрено 4 слота для команд. Если команд будет больше предусмотренного, турнир будет проведен на 6 команд. Формат может быть изменен."},{"slug":"ls-call-to-arms-2026","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм без турнирного билета, доступен для зрителей с задержкой 2 минуты при просмотре через друзей в матче."},{"slug":"ls-call-to-arms-2026","sortOrder":7,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-call-to-arms-2026","sortOrder":8,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - штраф времени I уровня. Опоздание от 20 до 30 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени II уровня. Опоздание от 30 минут до 45 минут - техническое поражение на первой карте и выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени III уровня. Опоздание более чем на 45 минут - техническое поражение в серии."},{"slug":"ls-call-to-arms-2026","sortOrder":9,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-call-to-arms-2026","sortOrder":10,"ruleText":"Тайбрейк на 3 команды играется на кастомной карте Overthrow 3.0 (5x3), при равном результате 2-х команд в группе выше ставится победившая в личной встрече (или переигровка бо1 турбо или CM, если личной встречи не было)."},{"slug":"ls-call-to-arms-2026","sortOrder":11,"ruleText":"Для участия в матче игрок обязан использовать игровой никнейм, указанный при регистрации на турнир."},{"slug":"ls-call-to-arms-2026","sortOrder":12,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры, которую будут использовать в каждом матче турнира."},{"slug":"ls-call-to-arms-2026","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-call-to-arms-2026","sortOrder":14,"ruleText":"Легионерами считаются игроки, не участвовавшие в серверных ивентах и лиге в период с 01.09.2025 по 26.01.2026. Они не должны иметь более 8500 MMR."},{"slug":"ls-call-to-arms-2026","sortOrder":15,"ruleText":"Правила могут меняться или дополняться как до, так и в ходе турнира."},{"slug":"ls-call-to-arms-2026","sortOrder":16,"ruleText":"1-ое место с группы, получают право выбрать противников на первую серию плэй-офф между командами 3-го и 4-го места"},{"slug":"ls-call-to-arms-2026","sortOrder":17,"ruleText":"Исходная таблица турнира: https://docs.google.com/spreadsheets/d/1dI4egfy9qUGGWBaFWlc8R5aAB94aPdTqaFPQ-uuOn18/edit"},{"slug":"ls-call-to-arms-2026","sortOrder":18,"ruleText":"Игроки-легионеры из команд, попавших в тройку лучших получают ледующие призы: Легионеры из команды, занявшей первое место - подписка Support1 на следующий сезон (продвинутая кастомизация роли) Легионеры из команды, занявшей второе место - Boosty-подписка на любую роль с цветной руной на 3 месяца Легионеры из команды, занявшей третье место - Boosty-подписка на роль \"Руна Воды\" на 3 месяца"},{"slug":"ls-draft-1","sortOrder":1,"ruleText":"Игроки регистрируются на турнир по ссылке."},{"slug":"ls-draft-1","sortOrder":2,"ruleText":"К регистрации допущены все игроки от ранга Герой включительно и до 8500 ММР. Допуск игроков к участию на усмотрение организатора."},{"slug":"ls-draft-1","sortOrder":3,"ruleText":"При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 40. В команде должен быть минимум 1 игрок 4-6 тира."},{"slug":"ls-draft-1","sortOrder":4,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одной карте за турнир. Замену нужно согласовать с организатором. Возможны исключения на усмотрение организатора."},{"slug":"ls-draft-1","sortOrder":5,"ruleText":"На турнире предусмотрено 4 слота для команд. Если команд будет больше предусмотренного, турнир будет проведен на 6 команды. Формат может быть изменен."},{"slug":"ls-draft-1","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм, без турнирного билета."},{"slug":"ls-draft-1","sortOrder":7,"ruleText":"Для участия в турнире все участники команды должны иметь любую Boosty-подписку."},{"slug":"ls-draft-1","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-draft-1","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени пика 2-го уровня. Опоздание от 20 до 30 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени пика 3-го уровня. Опоздание более чем на 30 минут - техническое поражение на первой карте и выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени пика 3-го уровня на всю серию. Присутствие команды - это 5 игроков в слотах игрового лобби и войс-канале одновременно."},{"slug":"ls-draft-1","sortOrder":10,"ruleText":"В случае назначения переигровок, игровые дни могут быть продлены, в случае тай-брейка между двумя командами, выше в таблице считается команда, которая победила в личной встрече между этими двумя командами. При тай-брейке на 3 команды играется Overthrow 3.0 (без раннего драфта для премиум-участников, но без запрета на рероллы) 5х3 или 3 круговых бо1 в тот же или в следующий день до старта полуфинала (старт не позже 16:00 финального игрового дня), если на это согласны все команды."},{"slug":"ls-draft-1","sortOrder":11,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-draft-1","sortOrder":12,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-draft-1","sortOrder":13,"ruleText":"Сформированные после драфта команды появятся в разделе Драфты составов."},{"slug":"ls-draft-1","sortOrder":14,"ruleText":"Легионерами считаются игроки не участвовавшие в ивентах 8-го тура лиги и 1-м туре лиги межсезонья."},{"slug":"ls-draft-1","sortOrder":15,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-draft-1","sortOrder":16,"ruleText":"Исходная таблица турнира: https://docs.google.com/spreadsheets/d/1U9_PfktDjJ8siS7_yNdEJ1e2HA_S9r7tOHVRgeebCaI/edit"},{"slug":"ls-draft-1","sortOrder":17,"ruleText":"Captain's Draft. Турнир для Boosty-подписчиков: капитаны выбирают игроков из пула. Минимальный ранг — Герой. Роли в архивном составе обозначают порядок записи и не подтверждают фактическую позицию в матчах."},{"slug":"ls-item-draft","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @10gu в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-item-draft","sortOrder":2,"ruleText":"К участию в турнире допускаются игроки, прошедшие регистрацию через турнирного бота и подтверждённые администратором. У игрока должна быть открыта история матчей на игровом аккаунте. После успешной проверки администратором игрок добавляется в официальную таблицу участников турнира."},{"slug":"ls-item-draft","sortOrder":3,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее в ивентах 8-го сезона Linken's Sphere. Исключение - два слота в команде может занять \"легионер\" (см п.17). Возможны исключения."},{"slug":"ls-item-draft","sortOrder":4,"ruleText":"Регистрировать можно только участников, которые отображены на странице Тир игроков, если участник отсутствует там, его нужно внести через @10gu @Son1c в Discord. При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 37."},{"slug":"ls-item-draft","sortOrder":5,"ruleText":"Команде разрешена не более одной замены за турнир. Замену можно использовать только на одной карте и она должна быть согласована с организатором. Форс-мажорные ситуации рассматриваются администрацией в индивидуальном порядке."},{"slug":"ls-item-draft","sortOrder":6,"ruleText":"На турнире предусмотрено 6 слотов для команд. Если команд будет меньше предусмотренного, турнир будет проведен на 4 команды. Формат может быть изменен."},{"slug":"ls-item-draft","sortOrder":7,"ruleText":"Матч проводится на сервере Стокгольм без турнирного билета, доступен для зрителей с задержкой 2 минуты при просмотре через друзей в матче."},{"slug":"ls-item-draft","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-item-draft","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - штраф времени I уровня. Опоздание от 20 до 30 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени II уровня. Опоздание от 30 минут до 45 минут - техническое поражение на первой карте и выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени III уровня. Опоздание более чем на 45 минут - техническое поражение в серии."},{"slug":"ls-item-draft","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-item-draft","sortOrder":11,"ruleText":"Тайбрейк на 3 команды играется на кастомной карте Overthrow 3.0 (5x3), при равном результате 2-х команд в группе выше ставится победившая в личной встрече (или переигровка бо1 турбо или CM, если личной встречи не было)."},{"slug":"ls-item-draft","sortOrder":12,"ruleText":"Для участия в матче игрок обязан использовать игровой никнейм, указанный при регистрации на турнир."},{"slug":"ls-item-draft","sortOrder":13,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры, которую будут использовать в каждом матче турнира."},{"slug":"ls-item-draft","sortOrder":14,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-item-draft","sortOrder":15,"ruleText":"Любому игроку может быть отказано в участии в турнире без объяснения причин. Турнирные тиры игроков устанавливаются на усмотрение организатора и не подлежат обсуждению."},{"slug":"ls-item-draft","sortOrder":16,"ruleText":"Правила могут меняться или дополняться как до, так и в ходе турнира."},{"slug":"ls-item-draft","sortOrder":17,"ruleText":"Легионерами считаются игроки не участвовавшие в турах лиги 8-го сезона и сыгравшие менее 70 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-item-draft","sortOrder":18,"ruleText":"1-ое место с группы, получают право выбрать противников на первую серию плэй-офф между командами 3-го и 4-го места"},{"slug":"ls-item-draft","sortOrder":19,"ruleText":"В рамках формата турнира Item Draft: Перед стартом карты команды банят предметы из утвержденного пула. Каждый предмет относится к одной из 9 категорий. Бан предмета запрещает его покупку и сборку через апгрейд. Бан действует на обе команды на текущую карту (В матчах серии бо3 бан предметов происходит перед каждой картой)."},{"slug":"ls-item-draft","sortOrder":20,"ruleText":"Перед началом каждой карты прооводится стадия бана предметов. Каждая команда: Получает 4 бана предметов; объявляет баны по очереди, устновленной регламентом (см. п.21). После бана предмет считается запрещенным к покупке и использованию в рамках карты. За нарушение правила предусмотрен штраф (см. п. 22)"},{"slug":"ls-item-draft","sortOrder":21,"ruleText":"Каждый предмет в пуле относится к одной категории. В рамках одной карты команда не может забанить более 1 предмета из одной категории. Команды путем подбрасывания монетки решают очередность банов. Команда, которая выиграла вбрасывание, решает очередность банов. Порядок Банов: A→A→B→B→A→B→B→A"},{"slug":"ls-item-draft","sortOrder":22,"ruleText":"Нарушениями считаются: Покупка запрещённого предмета; Сборка улучшений из запрещенного предмета. Штраф за нарушения: Непреднамеренная покупка запрещенного предмета → продажа предмета; Повторная покупка запрещенного предмета → техническое поражение; Использование купленного запрещенного предмета → техническое поражение."},{"slug":"ls-item-draft","sortOrder":23,"ruleText":"Исходная таблица турнира: https://docs.google.com/spreadsheets/d/1CRxkQJpmANpW0eOvJaRmSagbV4ksitwGsFv0-RCsY74/edit"},{"slug":"ls-pre-season-bash","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @frokeng в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-pre-season-bash","sortOrder":2,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее в лигах летнего DPC-межсезонья Linken's Sphere (участие в фасткапах и Overthrow не снимает статус \"легионера\"). Исключение - один слот в команде может занять \"легионер\" (см п.12), также, можно взять второго \"легионера\" со снижением суммарного тира команды на 1."},{"slug":"ls-pre-season-bash","sortOrder":3,"ruleText":"При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 36. Игроков 10 тира может быть не более одного на команду."},{"slug":"ls-pre-season-bash","sortOrder":4,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одну серию (bo1/bo3) за турнир, в таком случае замену выбирает команда, но её все ещё нужно согласовать с организатором. Также, возможно заменить игрока или двух игроков в любой момент в случае форс-мажора, ограничений на такие замены нет, но замену предоставляет организатор, в таком случае замена может не подходить по роли, если замена одна - она будет на 1 тир ниже, если замен сразу две - первая на 1 тир ниже, вторая на 2 тира ниже (при возникновении сложностей с поиском замены определенного тира, замена может быть предоставлена еще на 1 тир ниже или с тиром заменяемого игрока). При использовании замены в финале более чем на одну карту, призовые команды сокращаются на 20%."},{"slug":"ls-pre-season-bash","sortOrder":5,"ruleText":"На турнире предусмотрено 4 слотов для команд, формат может быть изменен."},{"slug":"ls-pre-season-bash","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм без турнирного билета, доступен для просмотра через друзей с задержкой 2 минуты."},{"slug":"ls-pre-season-bash","sortOrder":7,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-pre-season-bash","sortOrder":8,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - 3-й уровень штрафа бонус-времени на всю серию. Опоздание более чем на 20 минут - техническое поражение на первой карте серии, вторая карта ставится на 1 час 15 минут позже старта 1-й карты, возможен досрочный старт по договоренности."},{"slug":"ls-pre-season-bash","sortOrder":9,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-pre-season-bash","sortOrder":10,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере. Исключение - Sakana не является легионером."},{"slug":"ls-pre-season-bash","sortOrder":11,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-pre-season-bash","sortOrder":12,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-pre-season-bash","sortOrder":13,"ruleText":"Легионерами считаются игроки не участвовавшие в турах лиг в ходе DPC-межсезонья и сыгравшие менее 60 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-pre-season-bash","sortOrder":14,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-pre-season-bash","sortOrder":15,"ruleText":"Исходная таблица турнира: https://docs.google.com/spreadsheets/d/1Au9HbYhEyG3DIYuDzXG-pLUybA2ZvOibYExIqY1ZpMs/edit"},{"slug":"ls-pre-season-bash","sortOrder":16,"ruleText":"Переигровки на 3 команды играются в формате бо1 каждый с каждым в субботу в 19:50, при повторном равенстве по счёту играется Overthrow 3.0 на 3 команды. Переигровка на 2 команды играется по договоренности: или в формате соло мид 1х1 с заранее определенными правилами для игроков, или в формате бо1 в субботу в 19:50, при этом матч четвертьфинала стартует сразу после переигровки."},{"slug":"sd-fastcup-1","sortOrder":1,"ruleText":"Зарегистрировать состав на турнир можно через сообщение @frokeng в Discord. Нужно обозначить никнеймы игроков из \"Тир игроков\" и их номинальные роли."},{"slug":"sd-fastcup-1","sortOrder":2,"ruleText":"Турнир только для Boosty-подписчиков. У некоторых игроков с уровнями поддержки сервера 1 и 2 есть возможность давать \"подписочные\" слоты для игроков, не подписанных на Boosty, но не более 2 на команду."},{"slug":"sd-fastcup-1","sortOrder":3,"ruleText":"Любому игроку может быть отказано в участии в турнире без объяснения причин. Турнирные тиры игроков устанавливаются на усмотрение организатора и не подлежат обсуждению."},{"slug":"sd-fastcup-1","sortOrder":4,"ruleText":"Регистрировать можно только участников, которые отображены на странице Тир игроков, если участник отсутствует там, его нужно внести через @frokeng в Discord. При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 37."},{"slug":"sd-fastcup-1","sortOrder":5,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одной карте за турнир. Замену нужно согласовать с организатором."},{"slug":"sd-fastcup-1","sortOrder":6,"ruleText":"На турнире предусмотрено 4 слота для команд, возможно расширение до 6-8 слотов."},{"slug":"sd-fastcup-1","sortOrder":7,"ruleText":"Матч проводится на сервере Стокгольм и недоступен в разделе \"Просмотр\", турнирного билета нет. Через друзей можно смотреть матч с задержкой 2 минуты. Зрители разрешены."},{"slug":"sd-fastcup-1","sortOrder":8,"ruleText":"Запрещен обмен героями"},{"slug":"sd-fastcup-1","sortOrder":9,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам."},{"slug":"sd-fastcup-1","sortOrder":10,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 11 до 20 минут - возможность запретить определенный стат для определенного игрока (игрок не может взять героя силы/ловкости/интеллекта/универсального на выбор оппонента). Опоздание от 21 до 30 минут - возможность запретить определенный стат для всех игроков оппонента (игроки не может взять героя силы/ловкости/интеллекта/универсального на выбор оппонента). Опоздание более чем на 30 минут - техническое поражение на первой карте и штраф бонусного времени 3-го уровня и выбор стороны или очереди пика на достаются оппоненту на оставшихся картах. Присутствие команды - это 5 игроков в слотах игроковго лобби и войс-канале одновременно."},{"slug":"sd-fastcup-1","sortOrder":11,"ruleText":"При равенстве результата у команд, их места в турнирной таблице (групповой этап) определяются по следующим показателям (применяются поочерёдно): личная встреча (в случае 2 команд), тай-брейк в OW 3.0 (3 команды), где герой выбирается участниками случайно."},{"slug":"sd-fastcup-1","sortOrder":12,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"sd-fastcup-1","sortOrder":13,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"sd-fastcup-1","sortOrder":14,"ruleText":"В каждой команде может присутствовать не более 2 \"легионеров\". \"Легионер\" - игрок, не сыгравший ни одной игры на серверных ивентах 8-го сезона. Исключения - @Sakana"},{"slug":"sd-fastcup-1","sortOrder":15,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"sd-fastcup-1","sortOrder":16,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"sd-fastcup-1","sortOrder":17,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"sd-fastcup-1","sortOrder":18,"ruleText":"Исходная таблица турнира: https://docs.google.com/spreadsheets/d/17iABRQYXgFhSKZkER4WKlFEPmDCSRJ6ZgXbYJIZ6L8o/edit"}]
$rules$::jsonb) AS source(
  slug TEXT, "sortOrder" SMALLINT, "ruleText" TEXT
);

INSERT INTO tournament_rules (tournament_id, sort_order, rule_text)
SELECT tournament.id, source."sortOrder", source."ruleText"
FROM imported_fastcup_rules source
JOIN tournaments tournament ON tournament.slug = source.slug
ON CONFLICT (tournament_id, sort_order) DO NOTHING;

INSERT INTO tournament_team_results (application_id, placement, result_label)
SELECT application.id, source.placement, source."resultLabel"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
ON CONFLICT (application_id) DO NOTHING;

INSERT INTO tournament_prizes (
  tournament_id, placement, application_id, team_name_snapshot, prize_text
)
SELECT tournament.id, source.placement, application.id,
  source."teamName", source."prizeText"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
WHERE source.placement IS NOT NULL
ON CONFLICT (tournament_id, placement) DO NOTHING;

